    [Fact]
    public void Generated_Map_Reports_What_The_Hand_Written_Map_Did()
    {
        var current = AppliedModifierMap.Entries
            .Select(e => e.Modifier + ": " + string.Join(" | ", Types.Select(t => t.Name + "=" + (e.Target(t) ?? "-"))))
            .ToArray();
        Assert.Equal(Frozen, current);
    }
}